export class SmsWidget {
    menu = null;

    items = [
        { label: 'Add New', icon: 'pi pi-fw pi-plus' },
        { label: 'Remove', icon: 'pi pi-fw pi-trash' }
    ];
    devices = [
        { version: 'iOS 17.6', count: 1100 },
        { version: 'iOS 17.5', count: 602 },
        { version: 'iOS 17.4', count: 300 },
        { version: 'iOS 16', count: 420 },
        { version: 'iOS 15', count: 420 },
        { version: 'iOS 13', count: 420 }
    ];
    data: any;

    options: any;
    totalIOS: number = 0;
    totalAndroid: number = 0
    totalSMSFail: number = 0
    totalIpad: number = 0
    totalSMSSuccess: number = 0
    platformId = inject(PLATFORM_ID);
    @Input() dataReponseDevice: any;
    @Input() dataReponseSmsOtp: any;
    translationService = inject(TranslationService);

    constructor(private cd: ChangeDetectorRef,
        private t: TranslationService

    ) { }
    ngOnChanges(changes: SimpleChanges) {
        if (changes['dataReponseDevice'] && this.dataReponseDevice) {
            this.totalIOS = this.dataReponseDevice.reduce((sum: any, item: any) => sum + item.iosCount, 0);
            this.totalAndroid = this.dataReponseDevice.reduce((sum: any, item: any) => sum + item.androidCount, 0);
            this.totalIpad = this.dataReponseDevice.reduce((sum: any, item: any) => sum + item.ipadCount, 0);
        }

        if (changes['dataReponseSmsOtp'] && this.dataReponseSmsOtp) {
            this.totalSMSSuccess = this.dataReponseSmsOtp.reduce((sum: any, item: any) => sum + item.success, 0);
            this.totalSMSFail = this.dataReponseSmsOtp.reduce((sum: any, item: any) => sum + item.fail, 0);
            this.initChart();
        }
    }
    private langSub!: Subscription;

    ngOnInit(): void {
        this.langSub = this.t.lang$.subscribe((lang) => {
            const primengLocale = this.t['translations'][lang]?.primeng;
            if (primengLocale) {
                this.initChart()
            }
        });
    }
    ngOnDestroy() {
        this.langSub?.unsubscribe();
    }

    initChart() {
        if (isPlatformBrowser(this.platformId)) {
            const documentStyle = getComputedStyle(document.documentElement);
            const textColor = documentStyle.getPropertyValue('--p-text-color') || '#000';

            const labels = this.dataReponseSmsOtp.map((item: any) => {
                const monthNumber = parseInt(item.month.split('-')[1], 10);
                const lang = this.translationService.getLanguage?.() || this.translationService.getLanguage() || 'en';
                const date = new Date(2000, monthNumber - 1, 1);
                const monthName = new Intl.DateTimeFormat(lang, { month: 'long' }).format(date);
                return monthName.charAt(0).toUpperCase() + monthName.slice(1);
            })
            const successData = this.dataReponseSmsOtp.map((d: any) => d.success);
            const failData = this.dataReponseSmsOtp.map((d: any) => d.fail);

            this.data = {
                labels,
                datasets: [
                    {
                        label: this.translationService.translate('Common.Successfully'),

                        data: successData,
                        backgroundColor: '#1B84FF',
                        borderRadius: 6,
                        borderColor: '#ffffff'
                    },
                    {
                        label: this.translationService.translate('Common.Failed'),

                        data: failData,
                        backgroundColor: '#FF6F1E',
                        borderRadius: 6,
                        borderColor: '#ffffff'
                    }
                ]
            };

            this.options = {
                responsive: true,
                maintainAspectRatio: false,
                plugins: {
                    legend: {
                        position: 'top',
                        labels: {
                            color: textColor,
                            usePointStyle: true,
                            pointStyle: 'rectRounded'
                        }
                    }
                },
                layout: {
                    padding: 10
                },
                scales: {
                    x: {
                        stacked: false,
                        ticks: {
                            color: textColor
                        },
                        grid: {
                            display: false
                        }
                    },
                    y: {
                        ticks: {
                            color: textColor
                        },
                        grid: {
                            color: '#f0f0f0'
                        }
                    }
                }
            };

            this.cd.markForCheck();
        }
    }
}
